import {offerings,getOffering,offeringArtwork} from './craftkit-offerings.js';
import {productMockup} from './product-mockup.js';
const $=id=>document.getElementById(id);
const urls={'relic-island':'/','pattern-garden':'pattern-garden.html','chess-atelier':'chess.html'};
const samples={moves:[{from:'e2',to:'e4',color:'w'},{from:'e7',to:'e5',color:'b'},{from:'g1',to:'f3',color:'w'},{from:'b8',to:'c6',color:'b'},{from:'f1',to:'c4',color:'w'},{from:'g8',to:'f6',color:'b'},{from:'d2',to:'d3',color:'w'},{from:'f8',to:'c5',color:'b'},{from:'c1',to:'g5',color:'w'},{from:'d7',to:'d6',color:'b'},{from:'b1',to:'c3',color:'w'},{from:'c8',to:'e6',color:'b'}],trail:Array.from({length:70},(_,i)=>({x:Math.sin(i*.12)*8+i*.08,z:Math.cos(i*.08)*7,hue:.5+i*.004})),palette:'dusk',emblem:'sun',label:'10 coins / shrine awakened',motifs:['sun','moon','mountain','ocean']};
const portrait='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 300"><rect width="300" height="300" fill="#f0e6c7"/><ellipse cx="150" cy="261" rx="65" ry="7" fill="#15352f22"/><path d="M113 202h30v52h-30zm44 0h30v52h-30" fill="#574c3b"/><rect x="99" y="124" width="102" height="94" rx="28" fill="#28766c"/><circle cx="150" cy="95" r="38" fill="#e1b287"/><path d="M107 79l43-56 43 56Z" fill="#28766c"/><circle cx="137" cy="96" r="3" fill="#173c35"/><circle cx="163" cy="96" r="3" fill="#173c35"/><path d="M141 110q9 9 18 0" fill="none" stroke="#765238" stroke-width="3"/><path d="M111 132h78v19h-78zm54 9h20v56h-20" fill="#d7ac58"/></svg>';
const custom='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 300"><rect width="300" height="300" fill="#f0e6c7"/>'+Array.from({length:9},(_,i)=>`<path d="M${i%3*100} ${Math.floor(i/3)*100+100}l50-85 50 85Z" fill="${['#38777d','#ceaa5d','#b9704c'][i%3]}"/>`).join('')+'</svg>';
let category='accomplishment',selected='achievement-emblem';
function drawList(){const visible=offerings.filter(o=>o.category===category);$('offering-list').innerHTML=visible.map(o=>`<button class="offering-choice" data-offering="${o.id}" aria-pressed="${selected===o.id}"><strong>${o.title}</strong><small>${o.transformation}</small></button>`).join('');document.querySelectorAll('[data-offering]').forEach(b=>b.onclick=()=>{selected=b.dataset.offering;drawList();drawDetail();});}
function drawDetail(){const o=getOffering(selected),svg=o.renderer==='reference'?(o.id==='avatar-portrait'?portrait:custom):offeringArtwork(o.id,samples);$('offering-detail').innerHTML=`<span class="eyebrow">${o.category==='accomplishment'?'EARNED THROUGH PLAY':'DESIGNED THROUGH PLAY'}</span><h2>${o.title}</h2><p>${o.trigger}</p><p class="sample-source">${o.renderer==='moves'?'Sample match · 12 recorded moves':o.renderer==='journey'?'Sample route · 70 recorded positions':o.renderer==='reference'?o.id==='avatar-portrait'?'Sample customized explorer portrait':'Sample player-made mountain pattern':'Sample achievement · earned Sun sigil'}</p><div id="offering-preview"></div><label for="offering-format">Illustrative output<select id="offering-format">${o.formats.map(f=>`<option value="${f}">${f==='pendant'?'Pendant':f==='scarf'?'Scarf':'Pillow'}</option>`).join('')}</select></label><div class="detail-actions"><a href="${urls[o.game]}">Try it in a game ↗</a><button id="offering-export">Save example artwork ↓</button></div><details><summary>Plug this into your game</summary><p>Capture a stable gameplay event and the player’s artwork. CraftKit saves the design and story; Arcade supplies the available physical options, preview and checkout.</p><pre id="offering-code"></pre></details>`;
 const preview=()=>{$('offering-preview').innerHTML=productMockup($('offering-format').value,svg,'sun',selected==='achievement-evolution'?'ornate':'classic');};preview();$('offering-format').onchange=preview;
 $('offering-code').textContent=`await openOffering('${o.id}', {\n  sourceEventId: 'session-42:${o.id}',\n  type: '${o.formats[0]}',\n  design: { referenceSvg: gameArtwork },\n  story: [{ event: 'player-created-design' }]\n});`;
 $('offering-export').onclick=()=>{const filename=o.id+'-example.svg';if(window.webkit?.messageHandlers?.craftkitExport){window.webkit.messageHandlers.craftkitExport.postMessage({filename,base64:btoa(unescape(encodeURIComponent(svg)))});return;}const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
}
document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;selected=offerings.find(o=>o.category===category).id;document.querySelectorAll('[data-category]').forEach(c=>c.setAttribute('aria-pressed',String(c===b)));drawList();drawDetail();});drawList();drawDetail();
